import{C as d,o as s,c as r,a5 as e,E as a}from"./chunks/framework.URF5zJ_R.js";const y=JSON.parse('{"title":"67 道高频现场面试真题与深层考点 (Interview Prep)","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"11_Interview_Prep.md","filePath":"11_Interview_Prep.md","lastUpdated":1789008202000}'),o={name:"11_Interview_Prep.md"},x=Object.assign(o,{setup(g){const n=[{index:"01",title:"#1 45 分钟白板架构全流程掌控 (The 45-Min Framework)",category:"面试流程 · Core",desc:"白板面试的黄金铁律：需求澄清(5m) -> 容量粗算(5m) -> 高层架构(15m) -> 深度攻坚(15m) -> 容灾监控总结(5m)。时间耗尽是挂掉候选人的第一死因。",meta:{考察重点:"结构化思维、大局观与时间节奏把控",致命扣分:"开场一言不发直接画架构图或深陷局部细节"}},{index:"02",title:"#15 数据分片与分库分表键选择 (Sharding & Partition Key)",category:"数据存储 · Advanced",desc:"系统设计中最具决定性意义的核心决策。需权衡范围分片与哈希分片的优劣，以及如何避免跨分片关联查询与二次聚合开销。",meta:{考察重点:"水平横向伸缩与数据均匀分布能力",深度追问:"分片键为用户ID时如何应对头部 1% 大V热点倾斜"}},{index:"03",title:"#20 超卖与双并发扣减冲突 (Two Users Buy Last Item)",category:"并发事务 · Core",desc:"高并发库存扣减标准考题。深入对比数据库行级悲观锁 SELECT FOR UPDATE、乐观锁版本号控制与 Redis Lua 脚本原子预扣减方案。",meta:{考察重点:"并发事务隔离级别、行级锁开销与竞态解决",实战避坑:"切忌在应用内存完成判断后再裸写更新数据库"}},{index:"04",title:"#23 缓存击穿与热点 Key 过期 (Cache Stampede & Hot Keys)",category:"缓存架构 · Advanced",desc:"高并发下热点数据失效瞬间打垮数据库的工业防范方案：分布式互斥锁重建、后台概率性提前续期 (XFetch) 以及基础 TTL 叠加随机时间抖动。",meta:{考察重点:"缓存雪崩与击穿防范的多层级防御架构",实战避坑:"禁止对海量 Key 设置完全相同的过期时间"}},{index:"05",title:"#30 消息“恰好一次”消费神话 (Exactly-Once Processing)",category:"消息机制 · Advanced",desc:"诚实务实的工程技术直觉：分布式网络物理限制决定了没有绝对单向的恰好一次；真实工业界方案是“至少一次投递 (At-least-once) + 消费端业务幂等校验”。",meta:{考察重点:"分布式物理边界认知与幂等去重表设计",实战避坑:"轻信并向面试官吹嘘“中间件原生保证绝对恰好一次”"}},{index:"06",title:"#35 慢依赖隔离与防级联雪崩 (Bulkhead & Circuit Breaker)",category:"高可用韧性 · Advanced",desc:"微服务集群防雪崩核心军规：舱壁隔离机制 (Bulkhead)、独立线程池/连接池配额隔离、严格超时控制与熔断器 (Circuit Breaker) 快速失败兜底。",meta:{考察重点:"故障域隔离、降级兜底与防雪崩蔓延扩散",实战避坑:"所有下游 RPC 调用共用默认无上限的全局公共线程池"}}];return(i,t)=>{const l=d("CardGrid");return s(),r("div",null,[t[0]||(t[0]=e('<h1 id="_67-道高频现场面试真题与深层考点-interview-prep" tabindex="-1">67 道高频现场面试真题与深层考点 (Interview Prep) <a class="header-anchor" href="#_67-道高频现场面试真题与深层考点-interview-prep" aria-label="Permalink to &quot;67 道高频现场面试真题与深层考点 (Interview Prep)&quot;">​</a></h1><blockquote><p><em>考官在白板前真正提问的经典高频考题，深度揭示每一个问题背后考官真正考核的核心意图、避坑红线与高分关键点。</em></p></blockquote><hr><div class="tip custom-block"><p class="custom-block-title">💡 45 分钟白板面试黄金时间分配法则与考官视角</p><p>系统设计面试从来不是单纯考察“你知不知道某个中间件”，而是全面评估候选人的<strong>工程结构化思维、大局观、主动沟通意识与技术权衡自制力</strong>。</p><p><strong>推荐 45 分钟黄金时间分配法则</strong>：</p><ol><li><strong>00 - 05 分钟：需求与边界澄清 (Scope &amp; Clarification)</strong> —— 主动询问功能需求、非功能需求与用户规模，圈定设计边界；</li><li><strong>05 - 10 分钟：数量级估算 (Scale &amp; Estimation)</strong> —— 基于明确假设粗算读写 QPS、峰值乘数、存储年增量与网络带宽；</li><li><strong>10 - 25 分钟：高层架构与核心数据流 (High-Level Architecture)</strong> —— 绘制核心客户端、网关、微服务、数据存储与核心交互流程；</li><li><strong>25 - 40 分钟：深度攻坚与瓶颈推演 (Deep Dive &amp; Bottlenecks)</strong> —— 针对数据分片、热点倾斜、缓存失效、幂等一致性等核心痛点展开推演；</li><li><strong>40 - 45 分钟：监控容灾与总结权衡 (Wrap Up &amp; Observability)</strong> —— 阐明 SLO 指标、监控告警、容灾方案与如果拥有更多时间会做哪些优化。</li></ol></div><hr><h2 id="📊-题库全景多维看板" tabindex="-1">📊 题库全景多维看板 <a class="header-anchor" href="#📊-题库全景多维看板" aria-label="Permalink to &quot;📊 题库全景多维看板&quot;">​</a></h2><p>覆盖大厂白板面试与低阶对象设计的全考纲维度：</p><div class="stats-grid" style="margin-bottom:2rem;"><div class="stat-card"><div class="stat-icon">🎯</div><div class="stat-info"><span class="stat-number">67 道</span><span class="stat-label">现场白板原题库</span></div></div><div class="stat-card"><div class="stat-icon">🧭</div><div class="stat-info"><span class="stat-number">14 个</span><span class="stat-label">核心考察维度覆盖</span></div></div><div class="stat-card"><div class="stat-icon">🧩</div><div class="stat-info"><span class="stat-number">8 道</span><span class="stat-label">低阶设计 (LLD) 经典</span></div></div><div class="stat-card"><div class="stat-icon">⏱️</div><div class="stat-info"><span class="stat-number">45 分钟</span><span class="stat-label">黄金时间节拍模型</span></div></div><div class="stat-card"><div class="stat-icon">💡</div><div class="stat-info"><span class="stat-number">100%</span><span class="stat-label">考官意图与避坑解析</span></div></div></div><hr><h2 id="🌟-6-大现场面试标杆级核心真题剖析" tabindex="-1">🌟 6 大现场面试标杆级核心真题剖析 <a class="header-anchor" href="#🌟-6-大现场面试标杆级核心真题剖析" aria-label="Permalink to &quot;🌟 6 大现场面试标杆级核心真题剖析&quot;">​</a></h2><p>以下 6 道真题在大厂现场白板考核中具备极高权重，点击对应卡片快速审阅考点与避坑策略：</p>',11)),a(l,{items:n,columns:3}),t[1]||(t[1]=e('<hr><h2 id="📋-67-道高频现场面试原题与关键采分点全景对照表" tabindex="-1">📋 67 道高频现场面试原题与关键采分点全景对照表 <a class="header-anchor" href="#📋-67-道高频现场面试原题与关键采分点全景对照表" aria-label="Permalink to &quot;📋 67 道高频现场面试原题与关键采分点全景对照表&quot;">​</a></h2><p>支持在表格上方<strong>实时搜索过滤</strong>（如输入 <code>Databases</code>、<code>Caching</code>、<code>LLD</code>、<code>Advanced</code> 或关键词即刻筛选），在移动端将自动折叠为流式卡片：</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">考核类别</th><th style="text-align:left;">现场面试原题 (Question)</th><th style="text-align:left;">考官深层考察意图与关键采分点 (What they are testing)</th><th style="text-align:center;">难度</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>面试流程把控 (Process)</strong></td><td style="text-align:left;"><strong>设计 [X] 系统，限时 45 分钟</strong> (Design [X]. You have 45 minutes.)</td><td style="text-align:left;"><strong>首要考核结构化思维与节奏掌控</strong>：45分钟标准五步法（需求澄清 -&gt; 容量估算 -&gt; 高层架构 -&gt; 深度攻坚 -&gt; 容灾总结）。时间用尽是挂掉候选人的第一大死因。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>面试流程把控 (Process)</strong></td><td style="text-align:left;"><strong>这个系统的核心功能性需求是什么？</strong> (What are the functional requirements?)</td><td style="text-align:left;"><strong>开场 2 分钟内必须主动提问澄清</strong>，切忌等考官提醒。直接默认假设业务逻辑或一言不发开始画图是严重扣分点。</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>面试流程把控 (Process)</strong></td><td style="text-align:left;"><strong>我们要为多大的规模设计？</strong> (What scale are we designing for?)</td><td style="text-align:left;">主动明确日活 (DAU)、读写 QPS、峰值乘数与数据年增量。下游所有技术选型与分库分表决策均取决于该数字。</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>面试流程把控 (Process)</strong></td><td style="text-align:left;"><strong>估算该系统每年需要多少存储空间？</strong> (Estimate the storage this needs per year.)</td><td style="text-align:left;">基于明确假设展开<strong>数量级粗算 (Back-of-the-envelope)</strong>。数量级与推导逻辑大体正确即可，无需纠结小数点。</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>面试流程把控 (Process)</strong></td><td style="text-align:left;"><strong>你为什么选择这个数据库？</strong> (Why did you choose that database?)</td><td style="text-align:left;">考官会对白板上画的每一个方框发出灵魂拷问。必须结合读写模型、事务要求与查询复杂度论证选型，无理由选择直接失分。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>面试流程把控 (Process)</strong></td><td style="text-align:left;"><strong>你设计的这个系统瓶颈在哪里？</strong> (What is the bottleneck in your design?)</td><td style="text-align:left;"><strong>考察架构自省意识</strong>。瓶颈通常在单点数据库或网络 I/O。在考官开口前主动指出来并给出应对策略，能拿到极高评价。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>面试流程把控 (Process)</strong></td><td style="text-align:left;"><strong>当这个组件宕机崩溃时会发生什么？</strong> (What happens when this component fails?)</td><td style="text-align:left;">画在白板上的每一个节点都必须具备容灾故事情节（故障检测、副本选主切换、降级兜底）。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>面试流程把控 (Process)</strong></td><td style="text-align:left;"><strong>如果系统现在发生故障，你如何第一时间感知？</strong> (How would you know if this system was broken right now?)</td><td style="text-align:left;"><strong>可观测性意识</strong>。绝大多数未及格候选人从头到尾只字不提监控。必须主动说明核心业务指标、告警与健康检查探针。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>系统架构基石 (Fundamentals)</strong></td><td style="text-align:left;"><strong>解释 CAP 定理，并告诉我你的设计落在哪里？</strong> (Explain CAP theorem, then tell me where your design sits.)</td><td style="text-align:left;">考察理论在工程中的实际运用，而非死记硬背概念。网络分区必然存在，重点阐述一致性 (C) 与可用性 (A) 的取舍考量。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><strong>系统架构基石 (Fundamentals)</strong></td><td style="text-align:left;"><strong>这里采用强一致性还是最终一致性？给出理由。</strong> (Strong or eventual consistency here? Justify it.)</td><td style="text-align:left;">考察产品业务认知与工程平衡能力，而非纯技术偏好。转账余额需强一致，点赞计数完全可容忍最终一致。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong>系统架构基石 (Fundamentals)</strong></td><td style="text-align:left;"><strong>延迟 (Latency) 与吞吐量 (Throughput) 的本质区别是什么？</strong> (What is the difference between latency and throughput?)</td><td style="text-align:left;">极度基础但面试高压下频现口误。必须准确说清单请求处理时长 (P95/P99) 与单位时间内系统处理请求总量的差异。</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><strong>系统架构基石 (Fundamentals)</strong></td><td style="text-align:left;"><strong>如何将系统从 1,000 用户逐步扩展到 1000 万用户？</strong> (How do you scale this from 1,000 to 10 million users?)</td><td style="text-align:left;">考察阶段性架构演进叙事：单体应用 -&gt; 引入缓存 -&gt; 读写分离多副本 -&gt; 分库分表分片 -&gt; 微服务与异步消息解耦。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong>系统架构基石 (Fundamentals)</strong></td><td style="text-align:left;"><strong>为什么不直接换一台配置翻倍的超级大物理机？</strong> (Why not just use a bigger server?)</td><td style="text-align:left;">垂直扩展 (Scale-up) 的物理硬件瓶颈与陡峭成本曲线。同时实事求是指出：在初始业务量较小时垂直扩展确实是最廉价的方案。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;"><strong>数据存储与分片 (Databases)</strong></td><td style="text-align:left;"><strong>选 SQL 还是 NoSQL？请捍卫你的技术选择。</strong> (SQL or NoSQL for this? Defend your choice.)</td><td style="text-align:left;">技术决断力。在没有明确场景依据下，仅凭“支持海量并发”就草率选择 NoSQL，是面试官严重的扣分信号。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">15</td><td style="text-align:left;"><strong>数据存储与分片 (Databases)</strong></td><td style="text-align:left;"><strong>你会如何对数据进行分片？分片键是什么？</strong> (How would you shard this data? What is your partition key?)</td><td style="text-align:left;">整个系统设计最具决定性意义的核心决策。需论证范围分片与哈希分片的得失，以及跨分片关联查询的巨大开销。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">16</td><td style="text-align:left;"><strong>数据存储与分片 (Databases)</strong></td><td style="text-align:left;"><strong>如果分片键是用户 ID，头部 1% 的明星大 V 产生倾斜怎么办？</strong> (Your partition key is user ID. What about the top 1% of users?)</td><td style="text-align:left;"><strong>热点分片 (Hot Partitions) 连环追问陷阱</strong>。需提出加盐打散 (Salting)、多级只读缓存层与专门的头部大 V 热点独立通道。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">17</td><td style="text-align:left;"><strong>数据存储与分片 (Databases)</strong></td><td style="text-align:left;"><strong>如何在不全量迁移已有数据的前提下平滑扩容新增分片？</strong> (How do you add a shard without moving all the data?)</td><td style="text-align:left;">一致性哈希 (Consistent Hashing) 与虚拟节点算法。解释哈希环上新增节点仅需迁移相邻环段数据的优秀特性。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">18</td><td style="text-align:left;"><strong>数据存储与分片 (Databases)</strong></td><td style="text-align:left;"><strong>用户修改完个人资料后立即刷新却看到了旧版本，为什么？</strong> (A user updates their profile and sees the old version. Why?)</td><td style="text-align:left;">主从多副本复制延迟 (Replication Lag) 与写后即读一致性 (Read-your-writes consistency)。需给出写后短时定向查主库或版本号比对策略。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">19</td><td style="text-align:left;"><strong>数据存储与分片 (Databases)</strong></td><td style="text-align:left;"><strong>如何在 5 亿行高频活跃的核心大表上执行 DDL 表结构变更？</strong> (How do you handle a schema change on a live 500 million row table?)</td><td style="text-align:left;">考察真实的生产运维素养。阐明扩张-收缩模式 (Expand-Contract)、pt-online-schema-change、gh-ost 或影子表双写逐步同步机制。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">20</td><td style="text-align:left;"><strong>数据存储与分片 (Databases)</strong></td><td style="text-align:left;"><strong>两位用户同时下单抢购最后一件库存商品，详细推演交互过程。</strong> (Two users buy the last item simultaneously. Walk me through it.)</td><td style="text-align:left;">事务隔离与竞态冲突。对比悲观行锁 (<code>SELECT ... FOR UPDATE</code>)、乐观锁版本号过滤与 Redis Lua 原子预扣减方案。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">21</td><td style="text-align:left;"><strong>缓存架构与击穿 (Caching)</strong></td><td style="text-align:left;"><strong>在这个设计方案中，你会在哪些层级引入缓存？</strong> (Where would you add caching in this design?)</td><td style="text-align:left;">多级缓存全景思维：客户端本地/浏览器缓存 -&gt; 边缘 CDN -&gt; 反向代理网关缓存 -&gt; 应用进程内缓存 -&gt; 集中式 Redis 缓存集群。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">22</td><td style="text-align:left;"><strong>缓存架构与击穿 (Caching)</strong></td><td style="text-align:left;"><strong>你如何处理缓存失效与数据一致性难题？</strong> (How do you invalidate the cache?)</td><td style="text-align:left;">计算机科学最硬核的经典难题。权衡 Cache-Aside（失效旁路）、Write-Through、动态 TTL 与基于数据库变更捕获 (CDC) 的异步事件失效。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">23</td><td style="text-align:left;"><strong>缓存架构与击穿 (Caching)</strong></td><td style="text-align:left;"><strong>某热点 Key 突发过期导致数据库瞬间被打垮，如何防范？</strong> (A hot key expires and the database falls over. Prevent it.)</td><td style="text-align:left;"><strong>防范缓存击穿与雪崩 (Cache Stampede)</strong>。需给出分布式互斥锁重建、后台概率性提前续期 (XFetch) 以及基础 TTL 叠加随机时间抖动。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">24</td><td style="text-align:left;"><strong>缓存架构与击穿 (Caching)</strong></td><td style="text-align:left;"><strong>系统的缓存命中率预估是多少？如果骤降系统能撑住吗？</strong> (What is your cache hit rate, and what happens if it drops?)</td><td style="text-align:left;">考核是否为“缓存穿透/未命中后的数据库底层承载能力”做过防御性压测，不能把缓存当成不可替代的唯一存储底座。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">25</td><td style="text-align:left;"><strong>高并发伸缩 (Scaling)</strong></td><td style="text-align:left;"><strong>负载均衡器 (LB) 存在单点故障 (SPOF)，如何解决？</strong> (The load balancer is a single point of failure. Fix it.)</td><td style="text-align:left;">双机主备热切（Keepalived / VRRP）、DNS 多 IP 解析负载分担以及 Anycast BGP 路由注入容灾方案。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">26</td><td style="text-align:left;"><strong>高并发伸缩 (Scaling)</strong></td><td style="text-align:left;"><strong>一台新启动的应用节点是如何平滑开始接收生产流量的？</strong> (How does a new server start receiving traffic?)</td><td style="text-align:left;">服务注册与发现中心、健康检查探针 (Liveness/Readiness)、预热阶段 (Warm-up) 与灰度权重慢启动机制。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">27</td><td style="text-align:left;"><strong>高并发伸缩 (Scaling)</strong></td><td style="text-align:left;"><strong>线上突发 10 倍于预估的洪峰流量，哪个组件会最先崩溃？</strong> (Traffic is 10x forecast. What breaks first?)</td><td style="text-align:left;">深刻推演自身架构中最脆弱的短板环节。清晰分析连接池耗尽、带宽瓶颈还是 GC 停顿引发连锁反应。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">28</td><td style="text-align:left;"><strong>高并发伸缩 (Scaling)</strong></td><td style="text-align:left;"><strong>在极端极限高压流量下，你首先主动关停什么功能？</strong> (What do you turn off first under extreme load?)</td><td style="text-align:left;"><strong>优雅降级 (Graceful Degradation) 与主动甩负荷 (Load Shedding)</strong>。多数候选人从不主动提及非核心旁路功能（评论推荐、实时积分）的降级熔断。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">29</td><td style="text-align:left;"><strong>异步解耦与消息 (Messaging)</strong></td><td style="text-align:left;"><strong>为什么这里要放一个消息队列，而不是直接同步 RPC 调用？</strong> (Why put a queue here rather than calling directly?)</td><td style="text-align:left;">异步解耦、削峰填谷、故障重试隔离。同时必须能说明什么时候同步直接调用才是正确的（强依赖即时响应结果场景）。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">30</td><td style="text-align:left;"><strong>异步解耦与消息 (Messaging)</strong></td><td style="text-align:left;"><strong>如何保证分布式消息被“恰好一次 (Exactly-Once)”处理？</strong> (How do you guarantee a message is processed exactly once?)</td><td style="text-align:left;"><strong>诚实务实的工程直觉</strong>：网络物理限制决定了没有绝对的单向恰好一次；真实工业界方案是“至少一次投递 (At-least-once) + 消费端业务幂等校验”。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">31</td><td style="text-align:left;"><strong>异步解耦与消息 (Messaging)</strong></td><td style="text-align:left;"><strong>消费者处理批量消息时中途发生崩溃宕机，会发生什么？</strong> (The consumer crashes mid-batch. What happens?)</td><td style="text-align:left;">消息队列 Offset 提交策略（前置提交 vs 后置提交）、批量中途失败触发的重新投递以及重复消费防护。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">32</td><td style="text-align:left;"><strong>异步解耦与消息 (Messaging)</strong></td><td style="text-align:left;"><strong>某条消息持续重试消费失败，它最终应该去哪里？</strong> (A message fails repeatedly. Where does it go?)</td><td style="text-align:left;">死信队列 (DLQ - Dead Letter Queue)、最大重试上限、指数退避重试 (Exponential Backoff) 与报警通知人工补偿机制。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">33</td><td style="text-align:left;"><strong>异步解耦与消息 (Messaging)</strong></td><td style="text-align:left;"><strong>如何在保持并发并行消费的同时，严格保证消息处理顺序？</strong> (How do you preserve ordering while processing in parallel?)</td><td style="text-align:left;">基于业务主键 (Partition Key) 分区哈希路由。在单个分区内严格保证局部 FIFO 顺序，而不是去追求代价高昂且无法横向扩展的全局严格顺序。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">34</td><td style="text-align:left;"><strong>高可用与韧性 (Reliability)</strong></td><td style="text-align:left;"><strong>当下游依赖服务响应极慢时，前端用户界面会看到什么？</strong> (The downstream service is slow. What does the user see?)</td><td style="text-align:left;">超时机制 (Timeout)、熔断器 (Circuit Breaker) 与备选降级数据 (Fallback)。绝不能让用户面对无限转圈的死等状态。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">35</td><td style="text-align:left;"><strong>高可用与韧性 (Reliability)</strong></td><td style="text-align:left;"><strong>如何防止某一个慢依赖服务拖垮你整个核心服务集群？</strong> (How do you prevent one slow dependency from taking down your service?)</td><td style="text-align:left;">舱壁隔离 (Bulkheads)、线程池/连接池配额隔离、快速失败机制与熔断切断策略。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">36</td><td style="text-align:left;"><strong>高可用与韧性 (Reliability)</strong></td><td style="text-align:left;"><strong>请为这个 API 接口设计一套限流器 (Rate Limiter)。</strong> (Design a rate limiter for this API.)</td><td style="text-align:left;">高频独立必考题。必须熟练掌握令牌桶算法 (Token Bucket)、漏桶算法以及基于 Redis 滑动窗口的实现细节与适用场景。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">37</td><td style="text-align:left;"><strong>高可用与韧性 (Reliability)</strong></td><td style="text-align:left;"><strong>整个云区域/主数据中心发生毁灭性宕机，你的灾备预案是什么？</strong> (An entire region goes down. What is your plan?)</td><td style="text-align:left;">多地域异地多活 (Multi-Region)、恢复时间目标 (RTO) 与恢复点目标 (RPO)、数据跨区同步复制与 DNS 全球流量调度。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">38</td><td style="text-align:left;"><strong>高可用与韧性 (Reliability)</strong></td><td style="text-align:left;"><strong>你怎么能确定你的容灾故障切换方案线上真的管用？</strong> (How do you know your failover actually works?)</td><td style="text-align:left;"><strong>混沌工程 (Chaos Engineering) 与定期实战演练 (Game Days)</strong>。未经过线上模拟断网断电验证的容灾机制，在真正灾难来临时必然失效。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">39</td><td style="text-align:left;"><strong>全双工与长连接 (Real-time)</strong></td><td style="text-align:left;"><strong>客户端如何实时获知服务端产生的一条新消息？</strong> (How does the client learn about a new message?)</td><td style="text-align:left;">短轮询 (Polling)、长轮询 (Long Polling)、SSE (服务端推送事件) 与双向全双工 WebSocket 的深度选型与网络握手开销对比。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">40</td><td style="text-align:left;"><strong>全双工与长连接 (Real-time)</strong></td><td style="text-align:left;"><strong>系统需要维持 1000 万个持久长连接，如何组织架构？</strong> (You have 10 million persistent connections. How do you manage them?)</td><td style="text-align:left;">连接接入网关集群 (Connection Servers)、服务发现注册、操作系统 Epoll/文件句柄调优与全局长连接路由分发映射表。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">41</td><td style="text-align:left;"><strong>全双工与长连接 (Real-time)</strong></td><td style="text-align:left;"><strong>新消息到达时接收方用户正好处于离线断网状态，接下来怎么办？</strong> (The user is offline when the message arrives. Now what?)</td><td style="text-align:left;">离线消息持久化收件箱、移动端第三方推送通知 (APNs/FCM) 唤醒，以及用户重连上线后的差量同步与已读状态对齐。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">42</td><td style="text-align:left;"><strong>分布式鉴权与防御 (Security)</strong></td><td style="text-align:left;"><strong>一个用户请求在穿透多个微服务时，身份凭据是如何传递的？</strong> (How is a request authenticated across your services?)</td><td style="text-align:left;">API 网关完成初次认证并签发轻量内部 JWT/Context，内部服务间 mTLS 双向认证与跨链路上下文透传。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">43</td><td style="text-align:left;"><strong>分布式鉴权与防御 (Security)</strong></td><td style="text-align:left;"><strong>Token 应该在网关统一验证，还是在每个具体服务内部单独验证？</strong> (Where does the token get validated, and by whom?)</td><td style="text-align:left;">权衡网关集中验证（简单、内部服务免重复开销）与零信任 (Zero Trust) 架构下服务自治验证的安全性与网络架构假设。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">44</td><td style="text-align:left;"><strong>分布式鉴权与防御 (Security)</strong></td><td style="text-align:left;"><strong>恶意攻击者正在以极高频率刷爆你的 API 接口，如何防御？</strong> (Someone floods your API with requests. Respond.)</td><td style="text-align:left;">分级立体防御：边缘 WAF / DDoS 清洗、IP 黑名单、基于客户端特征的分布式频控拦截与动态人机验证 (CAPTCHA)。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">45</td><td style="text-align:left;"><strong>分布式鉴权与防御 (Security)</strong></td><td style="text-align:left;"><strong>系统数据受 GDPR 等隐私法案监管，你的架构设计需要发生什么改变？</strong> (This data is subject to GDPR. What changes in your design?)</td><td style="text-align:left;">考察法律法规对技术架构的塑造：数据物理驻留要求 (Data Residency)、被遗忘权（级联物理抹除）、静态加密与合规审计日志。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">46</td><td style="text-align:left;"><strong>可观测性追踪 (Observability)</strong></td><td style="text-align:left;"><strong>一个请求跨越 8 个微服务后出现严重延迟，你如何排查定位？</strong> (How would you debug a slow request across eight services?)</td><td style="text-align:left;">分布式全链路追踪体系 (OpenTelemetry / Jaeger / Zipkin)、透传全局 Correlation ID (TraceId/SpanId) 与日志采样归集分析。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">47</td><td style="text-align:left;"><strong>可观测性追踪 (Observability)</strong></td><td style="text-align:left;"><strong>针对你设计的这个系统，你的服务等级目标 (SLO) 是什么？</strong> (What is your SLO for this system?)</td><td style="text-align:left;">将可靠性量化为具备业务约束力的具体数字（如 99.95% 请求 P99 响应耗时 &lt; 200ms），并与错误预算和发布节奏紧密绑定。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">48</td><td style="text-align:left;"><strong>可观测性追踪 (Observability)</strong></td><td style="text-align:left;"><strong>系统告警应该针对什么触发？什么指标故意不触发电话告警？</strong> (What do you alert on, and what do you deliberately not alert on?)</td><td style="text-align:left;"><strong>监控症状而非原因</strong>：核心业务指标（如支付失败率、5xx 比例）触发紧急电话通知，单机 CPU 瞬时飙高仅做看板展示，规避告警疲劳。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">49</td><td style="text-align:left;"><strong>云成本与算力优化 (Cost)</strong></td><td style="text-align:left;"><strong>这个系统上线稳定运行后，每月的云基础设施账单大约是多少？</strong> (What does this system cost to run per month?)</td><td style="text-align:left;"><strong>商业成本敏感度</strong>。极少候选人具备估算服务器、托管数据库、对象存储与网络公网出向流量账单的综合能力。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">50</td><td style="text-align:left;"><strong>云成本与算力优化 (Cost)</strong></td><td style="text-align:left;"><strong>系统存储账单次月突然翻倍暴增，你的排查线索是什么？</strong> (Your storage bill doubled. Investigate.)</td><td style="text-align:left;">检查数据生命周期淘汰策略 (Retention)、冷热分层归档配置、多副本与快照膨胀，以及无节制写入且未压缩的应用日志。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">51</td><td style="text-align:left;"><strong>云成本与算力优化 (Cost)</strong></td><td style="text-align:left;"><strong>在完全不损伤终端用户体验的前提下，如何将现有系统成本砍半？</strong> (How would you reduce this cost by half without hurting users?)</td><td style="text-align:left;">边缘缓存分流、冷热数据压缩归档、计算资源精准降配 (Right-sizing)、引入预留实例 (Reserved Instances) 与竞价实例。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">52</td><td style="text-align:left;"><strong>架构权衡的艺术 (Trade-offs)</strong></td><td style="text-align:left;"><strong>这个系统应该采用微服务还是单体架构？</strong> (Should this be microservices or a monolith?)</td><td style="text-align:left;">对小型团队或初创业务，明确回答“应当优先采用良好模块化的单体架构 (Monolith)”能极大地赢得考官赞赏。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">53</td><td style="text-align:left;"><strong>架构权衡的艺术 (Trade-offs)</strong></td><td style="text-align:left;"><strong>这里为什么不选择使用当下流行的 Apache Kafka？</strong> (Why not use Kafka here?)</td><td style="text-align:left;">识别过度工程陷阱。在数据吞吐量适中、需要死信路由机制或仅为简单点对点解耦时，RabbitMQ/SQS 或直接同步调用往往更简单高效。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">54</td><td style="text-align:left;"><strong>架构权衡的艺术 (Trade-offs)</strong></td><td style="text-align:left;"><strong>如果有 10 倍的预算你会怎么改？如果预算砍半呢？</strong> (What would you do differently with 10x the budget? With half?)</td><td style="text-align:left;">检验候选人的技术方案是深思熟虑的理性推导结果，还是死记硬背照搬下来的唯一模板套路。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">55</td><td style="text-align:left;"><strong>架构权衡的艺术 (Trade-offs)</strong></td><td style="text-align:left;"><strong>能够满足当前业务需求的最简单、最纯粹的架构是什么？</strong> (What is the simplest thing that would work?)</td><td style="text-align:left;"><strong>工程自制力</strong>。在工业级系统研发中，过度设计 (Over-engineering) 带来的灾难往往远大于设计不足。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">56</td><td style="text-align:left;"><strong>面向对象低阶设计 (LLD)</strong></td><td style="text-align:left;"><strong>低阶设计 (LLD)：设计一个多楼层停车场系统。</strong> (Design a parking lot system.)</td><td style="text-align:left;">大厂现场 LLD 轮次最经典入门题。考察车辆类型多态继承、停车位分配算法与多种收费策略模式的解耦。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">57</td><td style="text-align:left;"><strong>面向对象低阶设计 (LLD)</strong></td><td style="text-align:left;"><strong>低阶设计 (LLD)：设计一个多部电梯调度系统。</strong> (Design an elevator system.)</td><td style="text-align:left;">状态模式 (State Pattern) 与电梯扫描调度算法 (SCAN/LOOK) 的面向对象实现，处理电梯运行、停止、开门与调度队列状态转换。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">58</td><td style="text-align:left;"><strong>面向对象低阶设计 (LLD)</strong></td><td style="text-align:left;"><strong>低阶设计 (LLD)：设计电影院在线订票系统 (BookMyShow)。</strong> (Design BookMyShow or a movie ticket booking system.)</td><td style="text-align:left;">类层级的多线程并发控制与临时锁定机制：选座预占 10 分钟倒计时锁、过期未付款释放与防多端重售。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">59</td><td style="text-align:left;"><strong>面向对象低阶设计 (LLD)</strong></td><td style="text-align:left;"><strong>低阶设计 (LLD)：设计群组记账与分摊结算系统 (Splitwise)。</strong> (Design Splitwise.)</td><td style="text-align:left;">账单数据实体建模与图算法优化：记录成员应收应付账单，并通过图简化算法将多人间的复杂转账次数降到绝对最低。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">60</td><td style="text-align:left;"><strong>面向对象低阶设计 (LLD)</strong></td><td style="text-align:left;"><strong>低阶设计 (LLD)：设计自动售货机系统 (Vending Machine)。</strong> (Design a vending machine.)</td><td style="text-align:left;">状态模式 (State Pattern) 的标准教科书范例：待机无币、已投币、已选货、出货中、找零各状态行为的封装隔离。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">61</td><td style="text-align:left;"><strong>面向对象低阶设计 (LLD)</strong></td><td style="text-align:left;"><strong>低阶设计 (LLD)：设计一个多渠道消息推送通知系统。</strong> (Design a notification system with multiple channels.)</td><td style="text-align:left;">策略模式 (Strategy Pattern) 与工厂模式 (Factory Pattern) 的优雅落地，支持短信、邮件、推送等新渠道插件式动态接入。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">62</td><td style="text-align:left;"><strong>面向对象低阶设计 (LLD)</strong></td><td style="text-align:left;"><strong>低阶设计 (LLD)：请指出这段设计代码具体违反了哪条 SOLID 原则？</strong> (Which SOLID principle does this design violate?)</td><td style="text-align:left;">LLD 代码重构与代码评审的标准基石：单一职责 (SRP)、开闭原则 (OCP)、里氏替换 (LSP)、接口隔离 (ISP) 与依赖倒置 (DIP)。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">63</td><td style="text-align:left;"><strong>面向对象低阶设计 (LLD)</strong></td><td style="text-align:left;"><strong>低阶设计 (LLD)：你刚才设计的这个类是线程安全的吗？请改造它。</strong> (Is this design thread-safe? Make it so.)</td><td style="text-align:left;">对象内部的底层并发原语实战：互斥锁 (Mutex)、读写锁、CAS 无锁原子操作或并发安全数据结构的正确选用。</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">64</td><td style="text-align:left;"><strong>项目经历与沟通软实力 (Practice)</strong></td><td style="text-align:left;"><strong>现场复盘：请详细向我介绍你曾经主导或深度参与构建的一个真实系统。</strong> (Walk me through the architecture of a system you have built.)</td><td style="text-align:left;">资深/高级工程师面试的最关键环节。考官会顺着你自己的真实项目细节层层深挖技术选型、翻车事故与故障排查过程。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">65</td><td style="text-align:left;"><strong>项目经历与沟通软实力 (Practice)</strong></td><td style="text-align:left;"><strong>你在技术生涯中所做过的最艰难、最具争议的技术决策是什么？</strong> (What is the hardest technical decision you have made?)</td><td style="text-align:left;">考核技术决断力与主人翁担当。需提前准备一段包含多方技术方案激烈碰撞、权衡妥协与最终业务收益的真实故事。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">66</td><td style="text-align:left;"><strong>项目经历与沟通软实力 (Practice)</strong></td><td style="text-align:left;"><strong>如果让你重新来过，你会对你负责过的线上系统做出什么重构或改变？</strong> (What would you change about a system you worked on?)</td><td style="text-align:left;">自省反思能力与工程认知成熟度。能够诚恳剖析历史架构包袱并给出成熟演进路径的候选人具备极高吸引力。</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">67</td><td style="text-align:left;"><strong>项目经历与沟通软实力 (Practice)</strong></td><td style="text-align:left;"><strong>请用完全非技术的日常语言，将这套复杂架构解释给产品总监或业务方听。</strong> (Explain this architecture to a non-technical stakeholder.)</td><td style="text-align:left;"><strong>决定资深技术专家定级的核心软实力</strong>：将 QPS、延迟、故障容灾等底层技术指标翻译为客户体验、资金安全与业务营收转化的跨部门沟通能力。</td><td style="text-align:center;"><code>Core</code></td></tr></tbody></table>',4))])}}});export{y as __pageData,x as default};
